const event = $json.event ?? $json;
const systems = { provider_event: 'provider', provider_result: 'provider', workflow_execution: 'workflow', tool_result: 'tool', brain_result: 'brain', crm_user: 'crm', system_reconciliation: 'system' };
const required = ['schema_version','event_id','idempotency_key','correlation_id','event_type','occurred_at','emitted_at','sequence','scope','source','payload'];
for (const key of required) if (!(key in event)) throw new Error(`crm_event_missing_${key}`);
if (event.schema_version !== 'lexia.crm.event.v1') throw new Error('crm_event_schema_unsupported');
for (const key of ['environment','cliente_slug','channel','account_ref','conversation_ref']) if (!event.scope?.[key]) throw new Error(`crm_scope_missing_${key}`);
if (systems[event.source?.authority] !== event.source?.system) throw new Error('crm_event_authority_system_mismatch');
if (event.event_type === 'appointment.confirmed' && event.source.authority !== 'tool_result' && event.source.authority !== 'system_reconciliation') throw new Error('crm_appointment_requires_tool_result');
if (event.event_type === 'message.delivery.updated' && event.source.authority !== 'provider_result' && event.source.authority !== 'system_reconciliation') throw new Error('crm_delivery_requires_provider_result');
return [{ json: { event } }];
